import React from 'react';

import {
  getAvailableQuarters,
  getClosedMonthIndex,
  QUARTER_MONTH_RANGES,
  QuarterKey,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

import { QUARTERS } from '../../constants';
import { useTimePeriodSliderPreview } from '../../hooks/useTimePeriodSliderPreview';
import { SliderAreaContainer } from '../../TimePeriodSelector.styles';
import { computeSliderPositions, getQuarterIndexFromEnd } from '../../utils';
import { QuarterBrackets } from '../QuarterBrackets';
import { StaticMonthLabels } from '../StaticMonthLabels';
import { TimePeriodSliderTrack } from '../TimePeriodSliderTrack';

interface QuarterSelectorProps {
  readonly cutoffDate: string;
  readonly selectedEnd: QuarterKey | null;
  readonly onEndChange: (end: QuarterKey) => void;
}

export function TimePeriodQuarterSelector({
  cutoffDate,
  selectedEnd,
  onEndChange,
}: QuarterSelectorProps) {
  const closedMonthIndex = getClosedMonthIndex(cutoffDate);
  const available = getAvailableQuarters(cutoffDate);
  const positions = computeSliderPositions(
    TimePeriodType.QTR,
    selectedEnd,
    closedMonthIndex,
  );

  const selectedQIdx = getQuarterIndexFromEnd(selectedEnd);
  const selectedQuarter = Object.values(QuarterKey)[selectedQIdx];
  const {
    startMonthIndex: selectedStartMonth,
    endMonthIndex: selectedEndMonth,
  } = QUARTER_MONTH_RANGES[selectedQuarter];

  const {
    isDragging,
    previewEnd,
    previewIndex: previewQuarterIndex,
    handleDraggingChange,
    handleValueChange,
    handleValueCommit,
  } = useTimePeriodSliderPreview<QuarterKey>({
    mapIndexToEnd: (idx) => {
      const quarterIndex = Math.max(0, Math.min(3, Math.floor(idx)));
      const q = QUARTERS[quarterIndex];
      return available.includes(q) ? q : null;
    },
    onCommit: onEndChange,
  });

  const previewPositions =
    isDragging && previewEnd !== null
      ? computeSliderPositions(TimePeriodType.QTR, previewEnd, closedMonthIndex)
      : null;

  return (
    <SliderAreaContainer data-testid="time-period-quarter-selector">
      <TimePeriodSliderTrack
        positions={positions}
        preview={isDragging ? previewPositions : null}
        isDragging={isDragging}
        sliderProps={{
          type: 'slider',
          min: 0,
          max: 3,
          maxInput: 3,
          step: 1,
          value: [
            isDragging ? (previewQuarterIndex ?? selectedQIdx) : selectedQIdx,
          ],
          callback: handleValueChange,
          onValueCommit: handleValueCommit,
          onDraggingChange: handleDraggingChange,
          thumbAriaLabel: 'Select quarter',
        }}
      />

      <StaticMonthLabels
        closedMonthIndex={closedMonthIndex}
        selectedMonthIndexes={[selectedStartMonth, selectedEndMonth]}
      />

      <QuarterBrackets
        getState={(quarter) => {
          const isEnabled = available.includes(quarter);
          return {
            active: selectedEnd === quarter,
            disabled: !isEnabled,
            muted: !isEnabled,
            ariaLabel: `Select ${quarter}`,
          };
        }}
        onSelect={onEndChange}
      />
    </SliderAreaContainer>
  );
}
